INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1763', 'その着せ替え人形は恋をする', '2022年冬', 'PR0046', 'TVシリーズ', 12, '『その着せ替え人形は恋をする』（そのビスクドールはこいをする）は、福田晋一による日本の漫画。『ヤングガンガン』（スクウェア・エニックス）において、2018年3号から2025年7号まで連載された。同誌2025年14号には単行本の最終巻の発売とテレビアニメのSeason 2の放送直前を記念した番外編が、同年16号には「スターゲイザー」のタイトルで特別読み切りが掲載された。略称は「着せ恋」（きせこい）。', 132405) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1764', 'ありふれた職業で世界最強 2nd season', '2022年冬', 'PR0093', 'TVシリーズ', 12, NULL, 112323) ON CONFLICT DO NOTHING;
