INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1766', 'ヴァニタスの手記 2クール', '2022年冬', 'PR0022', 'TVシリーズ', 12, NULL, 135136) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1767', '失格紋の最強賢者', '2022年冬', 'PR0006', 'TVシリーズ', 12, '『失格紋の最強賢者』（しっかくもんのさいきょうけんじゃ）は、進行諸島による日本のライトノベルおよびそれを原作とするメディアミックス作品。イラストは風花風花。サブタイトルは「〜世界最強の賢者が更に強くなるために転生しました〜」。略称は「失格紋」。 小説投稿サイト「小説家になろう」で連載中に2017年5月に書籍化された後、肝匠&馮昊（Friendly Land）の作画により、『マンガUP!』（スクウェ', 129191) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1768', '現実主義勇者の王国再建記 第二部', '2022年冬', 'PR0006', 'TVシリーズ', 13, NULL, 139648) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1769', '錆喰いビスコ', '2022年冬', NULL, 'TVシリーズ', 12, '『錆喰いビスコ』（さびくいビスコ）は、瘤久保慎司による日本のライトノベル。イラストは赤岸K、世界観イラストはmochaがそれぞれ担当している。電撃文庫 (KADOKAWA) より2018年3月から2025年1月まで刊行された。第24回電撃小説大賞の銀賞受賞作。防衛兵器の暴走によって文明が崩壊した未来の日本を舞台に、「錆び風」と呼ばれる現象に悩む人類と、それに対抗する力を持つ「キノコ守り」の青年の活', 130591) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1770', '佐々木と宮野', '2022年冬', 'PR0050', 'TVシリーズ', 12, '『佐々木と宮野』（ささき と みやの）は、春園ショウによる日本の漫画作品。春園がpixivに2015年2月から掲載していた『佐々木と宮野のちょっとした話。』を改題、商業化した作品であり、2016年より『ジーンピクシブ』（KADOKAWA）で連載化されている。2026年3月時点でシリーズ累計部数は270万部を突破している。 女顔がコンプレックスな宮野と、少し不良な先輩の佐々木を中心とした、男子高校生', 126288) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1771', '終末のハーレム', '2022年冬', 'PR0161', 'TVシリーズ', 11, '『終末のハーレム』（しゅうまつのハーレム、world''s end harem）は、LINK（原作）、宵野コタロー（作画）による日本の漫画作品。ウェブコミック配信サイト『少年ジャンプ+』（集英社 / 以降、『J+』と表記）にて、2016年5月8日から2023年5月7日まで、隔週日曜日に連載された。 難病を治療するためのコールドスリープから目覚めた主人公が、ウイルスによって男性が99.9%死滅した世界', 118465) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1772', '明日ちゃんのセーラー服', '2022年冬', 'PR0046', 'TVシリーズ', 12, '『明日ちゃんのセーラー服』（あけびちゃんのセーラーふく、英題：AKEBI''s sailor uniform）は博による日本の青年漫画。2016年から集英社のウェブコミックサイト『となりのヤングジャンプ』にて隔月連載中。 2025年4月時点で単行本の累計発行部数は125万部を突破している。 2023年7月からは作者の博が自身の『note』アカウントにて、ネーム段階で没にした登場人物たちのワンシーンを', 131548) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1773', '殺し愛', '2022年冬', 'PR0133', 'TVシリーズ', 12, '『殺し愛』（ころしあい）は、Feによる日本の漫画作品。『月刊コミックジーン』（KADOKAWA）にて、2015年11月号から2023年2月号まで連載された。連載開始前にはpixivでプロトタイプ版が執筆されていた。連載終了後、『月刊コミックジーン』にて2023年6月号より2024年3月号まで番外編が連載された。 『月刊コミックジーン』2018年3月号の付録でドラマCD化された。2020年12月にテ', 127050) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1774', '異世界美少女受肉おじさんと', '2022年冬', 'PR0034', 'TVシリーズ', 12, '『異世界美少女受肉おじさんと』（ファンタジーびしょうじょじゅにくおじさんと）は、原作：津留崎優、作画：池澤真による日本の漫画作品。『サイコミ』（Cygames）にて2019年11月18日から毎週月曜日更新で連載されている。サブタイトルは「ファ美肉おじさんと◯◯」。略称は『ファ美肉』、『ファ美肉おじさん』。', 134252) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1775', 'リアデイルの大地にて', '2022年冬', 'PR0025', 'TVシリーズ', 12, '『リアデイルの大地にて』（リアデイルのだいちにて）は、Ceezによる日本のライトノベル。小説家になろうにて2010年11月から2012年12月まで連載された。Web版の続編として『砂塵の向こう側にて』（小説家になろうで連載）、『リアデイルの大地より』（カクヨムで連載）の2作品がある。その後、単行本がファミ通文庫（KADOKAWA）よりB6判のサイズで2019年1月から刊行された。イラストはてんまそ', 130166) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1776', 'からかい上手の高木さん３', '2022年冬', 'PR0005', 'TVシリーズ', 12, NULL, 138424) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1777', 'プリンセスコネクト！Re:Dive Season 2', '2022年冬', 'PR0033', 'TVシリーズ', 12, NULL, 122808) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1778', '賢者の弟子を名乗る賢者', '2022年冬', 'PR0067', 'TVシリーズ', 12, '『賢者の弟子を名乗る賢者』（けんじゃのでしをなのるけんじゃ、英語: She professed herself pupil of the wise man.）は、りゅうせんひろつぐによる日本のライトノベル。略称は「賢でし」、「わしかわ」。小説投稿サイト『小説家になろう』にて、2012年4月4日から連載されていたWEB小説をもとに内容を加筆・修正し、2014年6月よりGCノベルズ（マイクロマガジン社', 119056) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1779', 'オリエント', '2022年冬', 'PR0150', 'TVシリーズ', 12, 'オリエント (Orient) は、広義では、ある地域から見て東方にある世界のこと。狭義では、古代ローマから見て東方にある世界のこと。日本で「オリエント」というときは、特に中東の「古代オリエント」を指すことが多い。', 128034) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1780', 'スローループ', '2022年冬', 'PR0064', 'TVシリーズ', 12, '『スローループ』 (SLOW LOOP) は、うちのまいこによる日本の漫画。芳文社刊行の『まんがタイムきららフォワード』にて、2018年6月号にゲスト掲載後、同年11月号より連載開始し、2025年4月号まで掲載された。その後、作者の療養により休載し、同年7月18日より『COMIC FUZ』に移籍して連載を再開した。', 127549) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1781', 'リーマンズクラブ', '2022年冬', 'PR0058', 'TVシリーズ', 12, '『リーマンズクラブ』は、ライデンフィルム制作による日本のオリジナルテレビアニメ作品。2022年1月から4月までテレビ朝日系列『NUMAnimation』枠ほかにて放送された。 バドミントンの実業団選手を題材とし、サラリーマンの日常およびスポーツ選手のドラマの2面を描いた作品。本作は『NUMAnimation』枠で初のテレビ朝日企画作品であり、テレビ朝日がバドミントンの中継権を保持していることが企画', 140502) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1782', '東京24区', '2022年冬', 'PR0046', 'TVシリーズ', 12, NULL, 140643) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1783', '薔薇王の葬列', '2022年冬', 'PR0006', 'TVシリーズ', 24, '『薔薇王の葬列』（ばらおうのそうれつ）は、菅野文による日本の歴史・ファンタジー漫画。ウィリアム・シェイクスピアの史劇『ヘンリー六世』および『リチャード三世』を原案とした作品で、『月刊プリンセス』（秋田書店）にて2013年11月号から2022年2月号まで連載された。同誌4月号より『薔薇王の葬列 外伝』のタイトルで番外編の連載が開始し、途中より『薔薇王の葬列 王妃と薔薇の騎士』のタイトルとなり、202', 124060) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1784', '怪人開発部の黒井津さん', '2022年冬', 'PR0124', 'TVシリーズ', 12, '『怪人開発部の黒井津さん』（かいじんかいはつぶのくろいつさん）は、水崎弘明による日本の漫画作品。『COMIC メテオ』（フレックスコミックス）にて2019年4月17日に読み切りが掲載され、2020年10月7日から2025年3月12日まで連載された。 悪の組織で予算や上司に振り回されながらも怪人開発に奮闘する主人公・黒井津燈香を描くコメディ。 2021年1月には単行本1巻の発売記念として、COMIC', 136428) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1785', 'ドールズフロントライン', '2022年冬', 'PR0012', 'TVシリーズ', 12, '『ドールズフロントライン』（Dolls'' Frontline）は、中華人民共和国のサンボーン（上海散爆網絡科技有限公司）が開発しているスマートフォン用のゲームアプリ。日本版はサンボーンジャパンの運営により、2018年8月1日にリリースされた。 原題は『少女前線』（しょうじょぜんせん、簡体字: 少女前线、英語: Girls'' Frontline）だが、後述のように日本版はリリース直前に改題された。日', 128828) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1786', 'ハコヅメ～交番女子の逆襲～', '2022年冬', 'PR0089', 'TVシリーズ', 13, NULL, 137312) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1787', 'トライブナイン', '2022年冬', 'PR0058', 'TVシリーズ', 12, NULL, 139804) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1788', 'フットサルボーイズ!!!!!', '2022年冬', 'PR0100', 'TVシリーズ', 12, '『フットサルボーイズ!!!!!』は、バンダイナムコアーツ・バンダイナムコエンターテインメント・ディオメディアによるメディアミックス作品。公式略称は「サルボ」。 「本気男子応援プロジェクト」として、アニメやゲーム、キャストが出演する試合イベントと連動したメディアミックスプロジェクトである。', 112719) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1789', 'CUE!', '2022年冬', NULL, 'TVシリーズ', 24, '『CUE!』（キュー）は、リベル・エンタテインメントより配信されていたスマートフォン向けアプリケーションゲーム。ジャンルは次世代声優育成ゲーム。サービス期間は2019年10月25日 - 2021年4月30日。基本プレイ無料（アイテム課金制）。 キャストには16名の新人女性声優を起用し、ゲームの展開とともに声優の育成も進めていくというプロジェクト。 2021年2月27日、アプリの改善に業務を集中させ', 125682) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1790', 'Shenmue the Animation', '2022年冬', 'PR0066', 'TVシリーズ', 13, NULL, 123752) ON CONFLICT DO NOTHING;
