INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1792', 'デリシャスパーティ♡プリキュア', '2022年冬', 'PR0039', 'TVシリーズ', 45, '『デリシャスパーティ♡プリキュア』（Delicious Party♡Precure）は、2022年2月6日から2023年1月29日まで、朝日放送テレビの制作により、テレビ朝日系列で毎週日曜8時30分から9時に放送された、東映アニメーション制作のテレビアニメ作品、および作中で主人公たちが変身するヒロインチームの名称。「プリキュアシリーズ」の通算19作目にして、17代目のプリキュアに当たる。 略称は「', 142080) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1793', '最遊記RELOAD -ZEROIN-', '2022年冬', 'PR0058', 'TVシリーズ', 13, NULL, 128400) ON CONFLICT DO NOTHING;
