INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1795', 'ニンジャラ', '2022年冬', 'PR0034', 'TVシリーズ', NULL, '『ニンジャラ』（英: Ninjala）は、2020年6月25日（JST）よりサービスが開始された、ガンホー・オンライン・エンターテイメント開発によるNintendo Switch用3D対戦アクションゲーム。基本プレイ無料（一部有料コンテンツあり）。2020年7月22日にはパッケージ版が発売された。', 142274) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1796', '爆丸エボリューションズ', '2022年冬', 'PR0070', 'TVシリーズ', 30, '『爆丸エボリューションズ』（ばくがんエボリューションズ、英名：Bakugan: Evolutions）は、スピンマスターおよびタカラトミーより発売されている男児向け玩具・爆丸を原案としたアニメ作品。カナダのスピンマスターおよびネルバナとの共同製作となる。 前作『爆丸ジオガンライジング』の直接の続編となる第4期シリーズ。2022年2月6日から10月23日までカナダのテレトゥーンで放送された。日本では', 146885) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1797', 'SPY×FAMILY', '2022年春', 'PR0046', 'TVシリーズ', 12, '『SPY×FAMILY』（スパイファミリー）は、遠藤達哉による日本の漫画。『少年ジャンプ+』（集英社、以下『J+』）において、2019年3月25日から隔週月曜更新で連載中。 遠藤にとって3作目の連載作品。赤の他人だったスパイの男、殺し屋の女、超能力者の少女が「仮初（かりそ）めの家族」を築き、「家族としての普通の日常」を送るために日々のトラブルと奮闘するホームコメディ。 本作の連載開始と同日発売の『', 140960) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1798', 'かぐや様は告らせたい-ウルトラロマンティック-', '2022年春', 'PR0001', 'TVシリーズ', 13, NULL, 125367) ON CONFLICT DO NOTHING;
