INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1800', 'サマータイムレンダ', '2022年春', 'PR0034', 'TVシリーズ', 25, '『サマータイムレンダ』（英語表記：Summer Time Rendering）は、田中靖規による日本の漫画。和歌山県和歌山市の離島を舞台としたSFサスペンス。ウェブコミック配信サイトおよびスマートフォンアプリ『少年ジャンプ+』（集英社）において、2017年10月23日から2021年2月1日まで毎週月曜日に配信された。通称「サマレン」。 連載完結後、メディアミックスとしてアニメ化、リアル脱出ゲーム化', 129201) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1801', '可愛いだけじゃない式守さん', '2022年春', 'PR0051', 'TVシリーズ', 12, '『可愛いだけじゃない式守さん』（かわいいだけじゃないしきもりさん）は、真木蛍五による日本の漫画作品である。『マガジンポケット』（講談社）にて2019年2月2日から2023年2月18日まで配信された。', 127911) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1802', '古見さんは、コミュ症です。2', '2022年春', 'PR0034', 'TVシリーズ', 12, NULL, 142984) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1803', '阿波連さんははかれない', '2022年春', 'PR0094', 'TVシリーズ', 12, '『阿波連さんははかれない』（あはれんさんははかれない）は、水あさとによる日本の漫画。ウェブコミック配信サイト『少年ジャンプ+』（集英社）2017年1月29日より2023年4月30日まで隔週日曜更新で連載された。 水あさとにとって9作目の連載作品であり、同人誌として発表していたオリジナル漫画作品『君との距離が測れない』を元としている。「低燃費系女子『阿波連さん』」を描く日常コメディ。 2024年12', 137281) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1804', '乙女ゲー世界はモブに厳しい世界です', '2022年春', 'PR0052', 'TVシリーズ', 12, '『乙女ゲー世界はモブに厳しい世界です』（おとめゲーせかいはモブにきびしいせかいです）は、三嶋与夢による日本のライトノベル。「小説家になろう」にて2017年10月から2019年10月まで連載され、書籍版がGCノベルズ（マイクロマガジン社）より2018年5月から2024年3月まで刊行された。イラストは孟達。略称は「モブせか」。『このライトノベルがすごい！2020』のランキングでは単行本部門の8位となっ', 142074) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1805', '骸骨騎士様、只今異世界へお出掛け中', '2022年春', 'PR0138', 'TVシリーズ', 12, '『骸骨騎士様、只今異世界へお出掛け中』（がいこつきしさま、ただいまいせかいへおでかけちゅう）は、秤猿鬼による日本のライトノベル。イラストはKeGが担当している。『小説家になろう』にて2014年10月から2018年7月まで連載された。書籍版がオーバーラップノベルス（オーバーラップ）より2015年6月から刊行されている。2026年4月時点で電子版を含めたシリーズの累計部数は350万部を突破している。', 132474) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1806', 'カッコウの許嫁', '2022年春', 'PR0005', 'TVシリーズ', 24, '『カッコウの許嫁』（カッコウのいいなずけ、英題：A Couple of Cuckoos）は、吉河美希による日本の漫画作品。『週刊少年マガジン』（講談社）にて2019年43号に読み切り作品として掲載後、読者アンケートの結果から同誌の2020年9号より連載を開始。', 132052) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1807', '史上最強の大魔王、村人Aに転生する', '2022年春', 'PR0024', 'TVシリーズ', 12, '『史上最強の大魔王、村人Aに転生する』（しじょうさいきょうのだいまおう むらびとエーにてんせいする）は、下等妙人による日本のライトノベル。Web版は小説家になろうにて2017年8月から2022年5月20日まで連載され、書籍版は富士見ファンタジア文庫（KADOKAWA）より2018年5月から2022年5月にかけて刊行された。イラストは水野早桜が担当した。2022年5月時点で電子版を含めたシリーズ累計', 130586) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1808', '勇者、辞めます', '2022年春', 'PR0060', 'TVシリーズ', 12, NULL, 140457) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1809', 'パリピ孔明', '2022年春', 'PR0083', 'TVシリーズ', 12, '『パリピ孔明』（パリピこうめい）は、原作：四葉夕卜、漫画：小川亮による漫画作品。『コミックDAYS』（講談社）にて、2019年12月31日から2021年11月16日まで連載。その後、同社の週刊誌『週刊ヤングマガジン』に移籍して、2021年52号より連載中。', 141774) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1810', 'アオアシ', '2022年春', 'PR0043', 'TVシリーズ', 24, '『アオアシ』は、小林有吾による日本の漫画作品。監修はスポーツライターの飯塚健司。Jリーグの男子高校生年代「Jユース」を扱っているサッカー漫画で、『ビッグコミックスピリッツ』（小学館）にて、2015年6号から2025年30号まで連載された。 2015年当時の『スピリッツ』副編集長が「Jユースを本格的に取り扱った漫画がない」ことに注目、企画された。そこで月刊スピリッツ誌上で読切「ショート・ピース」を発', 134732) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1811', '恋は世界征服のあとで', '2022年春', 'PR0019', 'TVシリーズ', 12, '『恋は世界征服のあとで』（こいはせかいせいふくのあとで）は、野田宏原作、若松卓宏作画による日本の漫画作品。略称は「恋せか」。『月刊少年マガジン』（講談社）にて、2019年11月号より2022年12月号まで連載。', 132010) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1812', 'デート・ア・ライブIV', '2022年春', 'PR0057', 'TVシリーズ', 12, NULL, 116605) ON CONFLICT DO NOTHING;
