INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1814', '本好きの下剋上 司書になるためには手段を選んでいられません 第3期', '2022年春', 'PR0004', 'TVシリーズ', 10, NULL, 121176) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1815', '魔法使い黎明期', '2022年春', 'PR0061', 'TVシリーズ', 12, '『魔法使い黎明期』（まほうつかいれいめいき）は、虎走かけるによる日本のライトノベル作品。それを原作・題材としたメディアミックス作品群。イラストはいわさきたかしが担当している。', 133175) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1816', '理系が恋に落ちたので証明してみた。r=1-sinθ（ハート）', '2022年春', 'PR0059', 'TVシリーズ', 12, NULL, 125124) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1817', 'であいもん', '2022年春', NULL, 'TVシリーズ', 12, '『であいもん』は、浅野りんによる日本の漫画作品。『ヤングエース』（KADOKAWA）にて2016年5月号より連載中。 「であいもん」という言葉自体は、京言葉で「食材同士が合わさることでお互いの良さを引き出す、取り合わせの良い食べ物」という意味を持つ。', 132532) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1818', 'ダンス・ダンス・ダンスール', '2022年春', 'PR0023', 'TVシリーズ', 11, '『ダンス・ダンス・ダンスール』（Dance Dance Danseur）は、ジョージ朝倉による日本の漫画。『週刊ビッグコミックスピリッツ』（小学館）にて、2015年42・43合併号から連載中。 バレエに密かな憧れを持って生きてきた主人公が、転校生との出会いをきっかけに、本気で男子バレエに取り組む姿を描いた青春譚。文化庁メディア芸術祭 第23回マンガ部門 審査委員会推薦作品。2024年4月時点で部数', 132171) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1819', 'まちカドまぞく 2丁目', '2022年春', 'PR0006', 'TVシリーズ', 12, NULL, 123330) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1820', 'BIRDIE WING -Golf Girls'' Story-', '2022年春', 'PR0114', 'TVシリーズ', 13, '『BIRDIE WING -Golf Girls'' Story-』（バーディーウイング ゴルフ ガールズ ストーリー）は、BN Pictures制作による日本のオリジナルテレビアニメ作品。Season 1は2022年4月から6月までテレビ東京系列ほかにて放送された。Season 2は2023年4月から6月までテレビ東京ほかにて放送された。', 140830) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1821', 'ヒロインたるもの！〜嫌われヒロインと内緒のお仕事〜', '2022年春', 'PR0131', 'TVシリーズ', 12, NULL, 138459) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1822', 'このヒーラー、めんどくさい', '2022年春', 'PR0011', 'TVシリーズ', 12, '『このヒーラー、めんどくさい』は、丹念に発酵による日本の漫画。2018年10月5日よりニコニコ静画で『これ、何の話ですか?』というタイトルで発表されていた同人漫画が、2019年7月31日よりタイトルを改めリメイクとして正式連載化。ニコニコ静画に加え、KADOKAWAが運営する『カドコミ』（旧ComicWalker）や『月刊コミックフラッパー』でも連載されている。『月刊コミックフラッパー』では202', 132351) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1823', 'くノ一ツバキの胸の内', '2022年春', 'PR0046', 'TVシリーズ', 13, '『くノ一ツバキの胸の内』（くノいちツバキのむねのうち）は、山本崇一朗による日本の漫画作品。『ゲッサン』（小学館）にて、2018年2月号から2023年6月号まで連載された。', 141350) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1824', 'キングダム 第4シリーズ', '2022年春', 'PR0035', 'TVシリーズ', 26, NULL, 140350) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1825', 'RPG不動産', '2022年春', 'PR0051', 'TVシリーズ', 12, '『RPG不動産』（アールピージーふどうさん、英: RPG Real estate）は、険持ちよによる日本の4コマ漫画。『まんがタイムきららキャラット』（芳文社）にて、2018年6月号から8月号のゲスト掲載を経て同年9月号から連載が開始され、2023年12月号をもって完結した。 タイトルの“RPG”について公式は「“Rent（賃貸） Plan（計画） Guide（案内）”の略」としている。冒険活劇で', 130319) ON CONFLICT DO NOTHING;
