INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1829', '社畜さんは幼女幽霊に癒されたい。', '2022年春', 'PR0019', 'TVシリーズ', 12, '『社畜さんは幼女幽霊に癒されたい。』（しゃちくさんはようじょゆうれいにいやされたい）は、有田イマリによる日本の漫画作品。有田がTwitterで発表した本作が話題になった後、『月刊少年ガンガン』（スクウェア・エニックス）にて2019年9月号から2026年2月号まで連載された。夜遅くまで会社で仕事に勤しむ、いわゆる社畜な伏原さんと、伏原の体調を心配して家に帰らせようと試みる幼い幽霊たちのやりとりを描く', 135384) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1830', 'ラブオールプレー', '2022年春', 'PR0147', 'TVシリーズ', 24, '『ラブオールプレー』（LOVE ALL PLAY）は、小瀬木麻美による日本の小説。2011年から2014年にかけてポプラ社より全4巻が発売された。 アニメ化に合わせて2021年に新装版が発売。2022年には番外編も発売。 バドミントンを題材とした青春物語を描いた小説。タイトルは試合開始時に審判が発する台詞から採られたものである。', 137633) ON CONFLICT DO NOTHING;
