INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1833', '群青のファンファーレ', '2022年春', 'PR0131', 'TVシリーズ', 13, '『群青のファンファーレ』（ぐんじょうのファンファーレ）は、Lay-duce制作による日本のテレビアニメ。2022年4月から6月にかけてTOKYO MXほかにて放送された。', 138452) ON CONFLICT DO NOTHING;
