INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1836', '遊☆戯☆王ゴーラッシュ!!', '2022年春', 'PR0036', 'TVシリーズ', 151, '『遊☆戯☆王ゴーラッシュ!!』（ゆうぎおうゴーラッシュ）は、ブリッジ制作による日本のテレビアニメ作品。2022年4月3日から2025年3月30日までテレビ東京系列にて放送された。全151話。「遊戯王ゴーラッシュ！！」と星マークを付けずに表記されることもある。', 142842) ON CONFLICT DO NOTHING;
