INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1841', 'よふかしのうた', '2022年夏', 'PR0058', 'TVシリーズ', 13, 'よふかしのうた  Creepy Nutsの楽曲。および配信シングル。楽曲の詳細は下記のアルバムの項を参照。 よふかしのうた (アルバム) - 上記楽曲が収録されたCreepy Nutsのミニアルバム。 よふかしのうた (漫画) - コトヤマの漫画。およびそのアニメ化作品。タイトルは上記楽曲に由来し、楽曲はアニメの第1期エンディングテーマに採用された。', 141391) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1842', 'ようこそ実力至上主義の教室へ 2nd Season', '2022年夏', 'PR0003', 'TVシリーズ', 13, NULL, 145545) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1843', 'リコリス・リコイル', '2022年夏', 'PR0001', 'TVシリーズ', 13, '『リコリス・リコイル』(Lycoris Recoil) は、A-1 Pictures制作による日本のアニメーション作品。アサウラのストーリー原案によるオリジナル作品である。2022年7月から9月にかけてBS11、TOKYO MXほかにて放送されたテレビアニメ。また、新作アニメの制作が決定しているほか、ショートムービー「『リコリス・リコイル』Friends are thieves of time.」', 143270) ON CONFLICT DO NOTHING;
