INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1848', '異世界おじさん', '2022年夏', 'PR0075', 'TVシリーズ', 13, '『異世界おじさん』（いせかいおじさん） は、「殆ど死んでいる」による漫画作品。略称は「いせおじ」。 Webコミック配信サイト『ComicWalker（現・カドコミ）』（KADOKAWA）にて2018年6月29日より連載を開始し、2021年6月16日より『WebComicアパンダ』に移籍して連載中。2026年4月時点で累計発行部数は555万部を突破している。 異世界から帰ってきたという男性「おじさん', 135806) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1849', 'ダンジョンに出会いを求めるのは間違っているだろうかⅣ 新章 迷宮篇', '2022年夏', 'PR0006', 'TVシリーズ', 11, NULL, 129196) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1850', '金装のヴェルメイユ～崖っぷち魔術師は最強の厄災と魔法世界を突き進む～', '2022年夏', 'PR0018', 'TVシリーズ', 12, NULL, 146210) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1851', '継母の連れ子が元カノだった', '2022年夏', 'PR0019', 'TVシリーズ', 12, '『継母の連れ子が元カノだった』（ままははのつれごがもとカノだった）は、紙城境介による日本のライトノベルおよびそれを原作とするメディアミックス作品。イラストは、たかやKiが担当している。2017年8月7日より「カクヨム」にて連載開始し、2018年12月から同社の角川スニーカー文庫により書籍化されている。略称は「連れカノ」。2024年10月時点で電子版を含めた全世界関連シリーズの累計部数は130万部を', 136934) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1852', '黒の召喚士', '2022年夏', 'PR0028', 'TVシリーズ', 12, '『黒の召喚士』（くろのしょうかんし）は、迷井豆腐の日本のライトノベル。2014年10月6日より小説投稿サイト「小説家になろう」で連載されていた『古今東西召喚士』という名の作品で、2015年5月16日に『黒の召喚士 〜戦闘狂の成り上がり〜』にタイトルが変更になった。2016年6月25日からオーバーラップ文庫（オーバーラップ）より書籍化刊行されている。2024年10月時点で電子版を含めたシリーズ累計部', 145260) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1853', 'Engage Kiss', '2022年夏', 'PR0001', 'TVシリーズ', 13, NULL, 146625) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1854', '異世界薬局', '2022年夏', 'PR0100', 'TVシリーズ', 12, '『異世界薬局』（いせかいやっきょく）は、高山理図による日本のライトノベル。小説投稿サイト『小説家になろう』にて2015年7月より連載されているオンライン小説で、加筆・修正されMFブックス（KADOKAWA）より2016年1月より書籍化刊行されている。書籍版のイラストはkeepoutが担当している。 メディアミックスとして、高野聖によるコミカライズが『コミックウォーカー』および『ニコニコ静画』に20', 136707) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1855', '組長娘と世話係', '2022年夏', 'PR0125', 'TVシリーズ', 12, '『組長娘と世話係』（くみちょうむすめとせわがかり）は、つきやによる日本の漫画作品。ウェブコミック配信サイト『コミックライドピクシブ』にて2018年6月5日から連載後、2020年5月より『コミックELMO』レーベルに移籍し、2023年11月30日に同レーベルも読むことができる『ライコミ』にリニューアルしてからも継続して連載中。2026年7月時点でシリーズ累計部数は170万部を突破している。', 138882) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1856', '転生賢者の異世界ライフ ～第二の職業を得て、世界最強になりました～', '2022年夏', NULL, 'TVシリーズ', 12, NULL, 129192) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1857', '異世界迷宮でハーレムを', '2022年夏', 'PR0021', 'TVシリーズ', 12, '『異世界迷宮でハーレムを』（いせかいめいきゅうでハーレムを）は、蘇我捨恥による日本のライトノベル。イラストは四季童子。2026年5月時点で電子書籍を含むシリーズ累計部数は700万部を突破している。 当初は小説投稿サイト「小説家になろう」にて『異世界迷宮で奴隷ハーレムを』（いせかいめいきゅうでどれいハーレムを）というタイトルで2011年4月より投稿されていたオンライン小説であったが、ヒーロー文庫（主', 127090) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1858', 'それでも歩は寄せてくる', '2022年夏', 'PR0024', 'TVシリーズ', 12, '『それでも歩は寄せてくる』（それでもあゆむはよせてくる）は、山本崇一朗による日本の漫画作品。『週刊少年マガジン』（講談社）2019年14号から連載開始、2023年50号を以て連載が終了した。2022年7月から9月までテレビアニメが放映された。 将棋部を舞台に繰り広げられる田中歩と八乙女うるしの高校生活を描いたラブコメディである。キャッチコピーは「この恋、詰むや詰まざるや……？」。話数表記は「第○局', 128223) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1859', '最近雇ったメイドが怪しい', '2022年夏', 'PR0008', 'TVシリーズ', 11, '『最近雇ったメイドが怪しい』（さいきんやとったメイドがあやしい）は、昆布わかめによる日本の漫画作品。スクウェア・エニックスの漫画雑誌『月刊ガンガンJOKER』にて連載。2019年10月17日以降、Twitterとpixivで投稿したことを契機に12月21日に公式連載化が決定し、2020年2月号（2020年1月22日発売）から公式連載を開始し、2024年10月号（2024年9月21日発売）まで連載さ', 149326) ON CONFLICT DO NOTHING;
