INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1862', '惑星のさみだれ', '2022年夏', NULL, 'TVシリーズ', 24, '『惑星のさみだれ』（ほしのさみだれ）は、水上悟志による日本の青年漫画。作者にとっては以前同誌で連載されていた『散人左道』に続く2本目の長期連載作品であり、『ヤングキングアワーズ』（少年画報社）にて2005年6月号から2010年10月号にかけて連載された。', 144323) ON CONFLICT DO NOTHING;
