INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1867', 'プリマドール', '2022年夏', 'PR0111', 'TVシリーズ', 12, 'プリマドール（Prima Doll）は、Keyによるメディアミックスプロジェクト。「歌と人形」をテーマにキャラクターたちの想いと成長を描く。', 144509) ON CONFLICT DO NOTHING;
