INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1870', 'うたわれるもの 二人の白皇', '2022年夏', 'PR0029', 'TVシリーズ', 28, '『うたわれるもの 二人の白皇』（うたわれるもの ふたりのハクオロ）は、アクアプラスより2016年9月21日に発売されたゲームソフト。対応機種はPlayStation 3、PlayStation 4、PlayStation Vita、Windows 10。', 112640) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1871', 'シャインポスト', '2022年夏', 'PR0138', 'TVシリーズ', 12, '『シャインポスト』（SHINE POST）は、コナミデジタルエンタテインメントとストレートエッジが共同で手掛けるメディアミックス作品。駱駝が執筆したライトノベルを原作とし、アニメ、ライブ、ゲームなど複数の媒体で展開される。', 140753) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1872', '神クズ☆アイドル', '2022年夏', 'PR0112', 'TVシリーズ', 10, '『神クズ☆アイドル』（かみクズアイドル）は、いそふらぼん肘樹による日本の漫画作品。『コミックZERO-SUM』（一迅社）にて2017年7月号に読み切りとして掲載後人気を得て、2018年2月号から連載された。', 142095) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1873', '連盟空軍航空魔法音楽隊ルミナスウィッチーズ', '2022年夏', 'PR0127', 'TVシリーズ', 12, '『連盟空軍航空魔法音楽隊ルミナスウィッチーズ』（れんめいくうぐんこうくうまほうおんがくたいルミナスウィッチーズ）は、島田フミカネ＆Projekt World Witches原作によるメディアミックス作品。同作の主要キャストによる9人組声優アイドルグループ「ルミナスウィッチーズ」についても本項で扱う。', 103118) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1874', 'てっぺんっ!!!!!!!!!!!!!!!', '2022年夏', 'PR0031', 'TVシリーズ', 12, NULL, 143417) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1875', 'ユーレイデコ', '2022年夏', 'PR0088', 'TVシリーズ', 12, '『ユーレイデコ』は、サイエンスSARU制作による日本のオリジナルテレビアニメ作品。2022年7月から9月までTOKYO-MXほかにて放送された。キャッチコピーは「ユーレイだけど、存在してる。」', 145468) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1876', 'Extreme Hearts', '2022年夏', 'PR0007', 'TVシリーズ', 12, '『Extreme Hearts』（エクストリームハーツ）は、都築真紀の原作および脚本、Seven Arcs制作による日本のテレビアニメ作品。略称は「エクハ」「ExH」。2022年7月10日から9月25日までTOKYO MX、BS11にて放送された。 主人公の葉山陽和とその仲間たちが夢に向かって頑張る物語。', 145001) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1877', 'シュート！Goal to the Future', '2022年夏', 'PR0060', 'TVシリーズ', 13, NULL, 141775) ON CONFLICT DO NOTHING;
