INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1879', 'カードファイト!! ヴァンガード will+Dress', '2022年夏', 'PR0042', 'TVシリーズ', 13, NULL, 139212) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1880', 'ちみも', '2022年夏', 'PR0005', 'TVシリーズ', 12, '『ちみも』は、シンエイ動画制作による日本のテレビアニメ。2022年7月から9月までテレビ東京・BS朝日ほかにて放送された。 キャラクター原案をイラストレーターのカナヘイが担当しており、魑魅魍魎たちを軸にした「ハートフル地獄コメディ」と銘打たれている。 1話で2つのエピソードが放送される構成となっており、全12話24エピソードが放送された。 テレビ放送に先駆けて2022年5月30日から6月23日にか', 144858) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1881', '5億年ボタン', '2022年夏', 'PR0110', 'TVシリーズ', 12, '5億年ボタン（ごおくねんボタン）は、2001年に菅原そうたにより発表された短編読み切り漫画の通称、およびそれを元にしたアニメである。', 150909) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1882', 'デュエル・マスターズWIN', '2022年夏', 'PR0048', 'TVシリーズ', 29, NULL, 153412) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1883', 'チェンソーマン', '2022年秋', 'PR0023', 'TVシリーズ', 12, '『チェンソーマン』（Chainsaw Man）は、藤本タツキによる日本の漫画。『週刊少年ジャンプ』（集英社）において第一部「公安編」が2019年1号から2021年2号まで連載され、第二部「学園編」は『少年ジャンプ+』（同社）において2022年7月13日から2026年3月25日まで連載された。2026年1月時点でシリーズ累計発行部数は3500万部を突破している。2022年にテレビアニメ化、2025年', 127230) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1884', 'SPY×FAMILY 第2クール', '2022年秋', 'PR0078', 'TVシリーズ', 13, NULL, 142838) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1885', 'ブルーロック', '2022年秋', 'PR0037', 'TVシリーズ', 24, '『ブルーロック』（BLUELOCK）は、原作：金城宗幸、作画：ノ村優介による日本の漫画。『週刊少年マガジン』（講談社）において、2018年35号から連載中。2021年5月には、第45回講談社漫画賞の少年部門を受賞した。2026年6月時点で累計発行部数は6000万部を突破している。スピンオフ作品として、『別冊少年マガジン』（同社）において三宮宏太が漫画を担当する『ブルーロック-EPISODE 凪-』', 137822) ON CONFLICT DO NOTHING;
