INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1890', 'BLEACH 千年血戦篇', '2022年秋', 'PR0035', 'TVシリーズ', 13, '『BLEACH 千年血戦篇』（ブリーチ せんねんけっせんへん）は、久保帯人による漫画『BLEACH』の最終章「千年血戦篇」を原作とする日本のテレビアニメシリーズ。テレビアニメ『BLEACH』の続編として制作され、分割4クール構成で順次放送されている。本作は、2020年3月に原作最終章のアニメ化として発表され、第1クールは2022年10月から12月まで、テレビ東京系列ほかにて放送された。 第2クール', 116674) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1891', '夫婦以上、恋人未満。', '2022年秋', 'PR0049', 'TVシリーズ', 12, '『夫婦以上、恋人未満。』（ふうふいじょう、こいびとみまん）は、金丸祐基（カナマル ユキ）による日本の漫画作品。『ヤングエース』（KADOKAWA）にて2018年4月号（2018年3月2日発売）より連載中。略称は『ふうこい』。同誌2025年5月号より長期休載している。 高校生の男女が授業の一環で疑似的な夫婦として生活させられる高校を舞台に、主人公とヒロインが、互いに片思いの相手とペアを組むべく夫婦を', 141949) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1892', '不滅のあなたへ Season 2', '2022年秋', 'PR0031', 'TVシリーズ', 20, NULL, 138565) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1893', '勇者パーティーを追放されたビーストテイマー、最強種の猫耳少女と出会う', '2022年秋', 'PR0060', 'TVシリーズ', 13, '『勇者パーティーを追放されたビーストテイマー、最強種の猫耳少女と出会う』（ゆうしゃパーティーをついほうされたビーストテイマー さいきょうしゅのねこみみしょうじょとであう）は、深山鈴による日本のライトノベル。イラストは8巻までをホトソウカが担当し、9巻以降を希が担当している。小説家になろうにて2018年6月から連載中で、Kラノベブックス（講談社）より2019年5月から刊行されている。略称は「ビステマ', 150695) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1894', 'うる星やつら (2022)', '2022年秋', 'PR0030', 'TVシリーズ', 23, NULL, 143277) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1895', '機動戦士ガンダム 水星の魔女', '2022年秋', 'PR0102', 'TVシリーズ', 12, '『機動戦士ガンダム 水星の魔女』（きどうせんしガンダム すいせいのまじょ、英：Mobile Suit Gundam THE WITCH FROM MERCURY）は、サンライズ制作による日本のテレビアニメ。 「ガンダムシリーズ」に属するロボットアニメであり、『機動戦士ガンダム 鉄血のオルフェンズ』（第2期）以来5年ぶりとなるTBS系列毎日放送製作日曜午後5時枠（『日5』枠）の新作アニメとして、Se', 139274) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1896', '魔入りました！入間くん 第3シリーズ', '2022年秋', 'PR0114', 'TVシリーズ', 21, NULL, 139092) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1897', 'アキバ冥途戦争', '2022年秋', 'PR0083', 'TVシリーズ', 12, '『アキバ冥途戦争』（アキバめいどせんそう、Akiba Maid War）は、CygamesとP.A.WORKS制作の日本のテレビアニメ。2022年10月から12月までTOKYO MXほかにて放送された。', 151379) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1898', '宇崎ちゃんは遊びたい！ω（だぶる）', '2022年秋', 'PR0052', 'TVシリーズ', 13, NULL, 124395) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1899', '恋愛フロップス', '2022年秋', 'PR0021', 'TVシリーズ', 12, '『恋愛フロップス』（れんあいフロップス）は、パッショーネによる日本のアニメーション作品・オリジナル作品である。2022年10月から12月までAT-Xほかにて放送された。 普通の男子高校生が、5人の少女たちとの恋愛模様に巻き込まれる姿を描いたオリジナルアニメ作品である。', 146676) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1900', '忍の一時', '2022年秋', 'PR0081', 'TVシリーズ', 12, '『忍の一時』（しのびのいっとき）は、DMM picturesとTROYCAによる日本のテレビアニメ。2022年10月から12月までAT-Xほかにて放送された。', 145604) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1901', '農民関連のスキルばっか上げてたら何故か強くなった。', '2022年秋', 'PR0067', 'TVシリーズ', 12, '『農民関連のスキルばっか上げてたら何故か強くなった。』（のうみんかんれんのスキルばっかあげてたらなぜかつよくなった）は、しょぼんぬによる日本のライトノベル。 2016年8月2日から2018年5月16日まで小説投稿サイト「小説家になろう」で連載されていた作品で、2017年3月から2018年11月にかけてモンスター文庫（双葉社）より書籍化刊行された。2022年3月時点でシリーズ累計発行部数は80万部を', 145815) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1902', 'Do It Yourself!! -どぅー・いっと・ゆあせるふ-', '2022年秋', 'PR0027', 'TVシリーズ', 12, '『Do It Yourself!! -どぅー・いっと・ゆあせるふ-』は、DIY（＝Do It Yourself）をテーマとする、PINE JAM制作による日本のテレビアニメ作品。2022年10月から12月までテレビ東京ほかにて放送された。', 131516) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1903', 'アークナイツ 黎明前奏', '2022年秋', 'PR0047', 'TVシリーズ', 8, NULL, 140660) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1904', '後宮の烏', '2022年秋', 'PR0114', 'TVシリーズ', 13, '『後宮の烏』（こうきゅうのからす）は、白川紺子による日本のライト文芸。イラストは香魚子が担当している。集英社オレンジ文庫（集英社）より2018年4月から2022年4月まで刊行された。 中華風の世界観を舞台に、後宮の奥深くに住む「烏妃」と呼ばれる特別な妃と、噂を頼って彼女の元を訪れた皇帝を中心に描くファンタジー小説となっている。2022年8月時点でシリーズ累計発行部数は120万部を突破しており、集英', 142701) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1905', '不徳のギルド', '2022年秋', 'PR0080', 'TVシリーズ', 12, '『不徳のギルド』（ふとくのギルド）は河添太一による日本の漫画作品。『月刊少年ガンガン』（スクウェア・エニックス）にて、2017年7月号（6月12日発売）より連載中。2024年3月時点で累計部数が200万部を突破している。', 146233) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1906', 'ゴールデンカムイ 第四期', '2022年秋', 'PR0048', 'TVシリーズ', 13, NULL, 142343) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1907', '虫かぶり姫', '2022年秋', 'PR0089', 'TVシリーズ', 12, '『虫かぶり姫』（むしかぶりひめ）は、由唯による日本のライトノベル。イラストは椎名咲月が担当している。2015年9月から2022年1月まで『小説家になろう』にて連載され、2016年7月から書籍版がアイリスNEO（一迅社）より刊行されている。 メディアミックスとして、『コミックZERO-SUM』（一迅社）にて喜久田ゆいによるコミカライズ版が2018年10月号より連載されている。2022年10月から12', 144533) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1908', '新米錬金術師の店舗経営', '2022年秋', 'PR0052', 'TVシリーズ', 12, '『新米錬金術師の店舗経営』（しんまいれんきんじゅつしのてんぽけいえい）は、いつきみずほによる日本のライトノベル。2018年11月からWeb小説として「小説家になろう」にて連載を開始し、2019年9月から富士見ファンタジア文庫（KADOKAWA）より書籍版の刊行が開始。イラストはふーみ。書籍版の刊行後は、KADOKAWAが運営する「カクヨム」でもWeb版が掲載されるようになった。 「小説家になろう」', 139369) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1909', 'ベルセルク 黄金時代篇 MEMORIAL EDITION', '2022年秋', NULL, 'TVシリーズ', 13, NULL, 155011) ON CONFLICT DO NOTHING;
