INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1912', '4人はそれぞれウソをつく', '2022年秋', 'PR0016', 'TVシリーズ', 11, '『4人はそれぞれウソをつく』（よにんはそれぞれウソをつく）は、橿原まどかによる日本の漫画。2018年にネーム原作賞受賞後、『別冊少年マガジン』（講談社）にて、2020年5月号から2023年4月号まで連載。略称は「4ウソ」。 それぞれ誰にも言えない秘密を抱えている仲良し女子中学生4人組の姿を描く学園コメディ作品。毎話4コマ漫画と5コマ漫画が連続する構成となっている。 2022年10月から12月までテ', 146962) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1913', 'C団地', '2022年秋', 'PR0092', 'TVシリーズ', 4, NULL, 146475) ON CONFLICT DO NOTHING;
INSERT INTO animes (anime_id, title, broadcast_season, production_id, type, episodes, synopsis, anilist_id) VALUES ('AN1914', 'うちの師匠はしっぽがない', '2022年秋', 'PR0058', 'TVシリーズ', 13, '『うちの師匠はしっぽがない』（うちのししょうはしっぽがない）は、TNSKによる日本の漫画作品。『good!アフタヌーン』（講談社）にて、2019年2号より2024年2号まで連載された。上方落語を題材に、主人公の成長と師弟愛を描く。', 137341) ON CONFLICT DO NOTHING;
